BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (303::BIGINT, 'Cuenta unas historias perversas o divertidas en clase. Al dar la clase no le vas a entender casi que nada, lo bueno es que todo lo que explica va en un word que sube que podes leer después. Es muy estricto y todos los trabajos que manda son hechos por IA, en revisiones es un dolor de cabeza.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Pocos exámenes']::TEXT[], '2026-11-02T00:00:00+00:00'::TIMESTAMPTZ, '3d15b510eb680b58511a7804879f78d5ff4737740fbd7f2543ae324a4f269c64'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'En clase no se aprende nada, toca ser autodidacta. Casi todo el curso es virtual a menos que hayan quices. En todas las clases sale con sus historias, algunas graciosas y otras muy perversas. Son 4 tareas y ya, realmente pasar con él no es tan difícil, pero sí muy cansado. Habla muy golpeado.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-10-19T00:00:00+00:00'::TIMESTAMPTZ, 'e57d60274dc84222a08a510c63063aef85093211393b5e14619d2d9214f07c20'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'No espere aprender mucho con el, casi que todo va a ser por su cuenta. Ademas, que se enoja si uno no hace las cosas como el quiere. Las revs son un azar, a veces esta de buen humor(casi nunca) y califica bien. Pero pidale ayuda y le va ayudar. Buena persona y vacilon. Se aprende de plantas maestras'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'fe81fbe44a9977fc9d3572e93f6e087edf37d9535528fc380e178d37deeab95f'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'El profe como persona es muy bueno cuenta historias interesantes, pero gasta todo ese tiempo en las clases por lo que el aprendizaje es prácticamente nulo todo lo aprendido tiene que ser por cuenta propia, los proyectos son dificultad intermedia y los exámenes son para rascar puntos'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '4769c25d0b8a008f3074c94299294010db6d7e07f98ccbc58c9f1207017ad506'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'No espere aprender con lo que ve en clase. El 90% lo va a tener que investigar por usted mismo. En clase pierde MUCHO (MUCHO) tiempo hablando de otras cosas. Los proyectos son relativamente sencillos, y como persona en realidad es una teja. Como profesor no es el mejor. Evite revisiones a las 2 00AM'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Exámenes retadores']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '81ba45a235e43f65333a142f9e55b0a0e64d52b0f858dde2fe5acf4f33b18181'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'No sirve para enseñar. La primeras semanas se la pasó hablando de sintoismo y cosas así en vez de enseñar. Todo el semestre estuvimos atrasados porque el no enseña, solo lee diapositivas por 20min y prosigue a hacer un ejercicio (que no le sale) y despues usa ChatGPT para que haga el ejercicio.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '70cca1ba8256586788c7ea6429c9e0ccc32ea9ae8abbd4269e5c72e5452df34a'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'Franki es un caso, pero meta con él en vez de nuñez. El mae se distrae y se pone a contar historias y mucho se termina aprendiendo solo, pero con solo que en los proyectos le muestre lo que va haciendo y le pregunte mucho, las revisiones son más fáciles y pasa sin problema. exime parte del 2° examen'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2026-01-20T00:00:00+00:00'::TIMESTAMPTZ, '5970344b5399a19f7ce92b734d2b6d7e9854d8114aabfd15809a76b9848f4be4'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Si perder el tiempo tuviera nombre se llamaria Franco Quiros. Habla de todo menos de la materia, examenes voladisimos comparado con lo que enseña, el diseño de BD lo hace él en los proyectos, o sea, no se aprende a diseñar. Se aprende más de la vida personal del sujeto que de la materia NO MATRICULE'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-11-14T00:00:00+00:00'::TIMESTAMPTZ, '36353fe092f95aa5f997c410de4c706ecd3c82ee86ad0c72d52f210b658f3114'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Habla mucha paja, se desvía de la materia sumamente fácil y pierde el enfoque de lo que dice, habla de lo mismo casi todo el semestre, no se aprende casi nada, revisiones en la madrugada, con Rodrigo es más difícil pero se aprende más. Si quiere aprender de verdad no meta con él. Se pasa con 60'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-10-22T00:00:00+00:00'::TIMESTAMPTZ, '4cd3b7bba7e7c3c33cf942b09acb6d0b563bd5e2b2de1fdfbf6607aa7be3d401'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Bastante enredado, habla temas que no son, llevelo con el solo si tu carrera no ocupa saber bien como programar, las tareas son largas y los examenes dificiles'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'd249e88028685b127f40ffcbcabb4889bf87b8a2f643ab26d54bdaad8db5eb8a'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'Es un profesor agradable, pero no lo recomiendo para nada, si no sabes nada de python es una tortura, pierde mucho el tiempo en clases hablando de cosas ajenas a la materia, lleva el programa el curso como le da la gana, los examenes y tareas son mil veces mas dificiles que los ejemplos vistos en cl'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'dfa0deb64c99797bc7344a55c3612347999fb323c9fcda4ca53ca084923e4355'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'Llevé el curso con él porque no me quedaba nadie más, y sinceramente fue desperdiciar la matrícula. Habla demasiado, no enseña lo necesario y exige mucho al estudiante. Si es la única opción mejor espere al siguiente semestre.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'd60b79e958ef4700ad53141bf6ce79dd92f72e4464d5ce2d8b2cb500357ab88e'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Se le dificulta explicar. Aun que sus intenciones de enseñar son genuinas no lo hace de la mejor forma, puede llegar a ser delicado y brusco con los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-05-23T00:00:00+00:00'::TIMESTAMPTZ, '3300643225401921ee4b4e06bfb84f30c118b3d420b723dff6c74ede1f68a778'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'No se le entiende nada de las progras, examenes dificiles y quices raros, mejor deje el curso para el semestre que viene'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2025-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'bb8250d10e4b4b225a36240e8bb2156ae4f9bbfcabd0e6f74a41fb308c53b328'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Realmente como profesor es malo, durante el semestre no se aprendió absolutamente nada, las clases son eternas y aburridas. Pero si ve que usted le echa ganas le ayuda'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '0b31df27b516db0a8b09ef9b0fd3477e7da70d78e3f24547824402ac1f9ee16d'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'Explica desde lo más básico posible, aclara dudas, pero son clases bastante aburridas. Recomiendo practicar bastante y ser autodidacta, si va solo con lo visto en clase las pruebas se complican un poco. Recomiendo solo si no tiene problema con aprender por su cuenta.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '819fe9b56693c8c86ce6d459dad9b07d7836b96123c33b7ec60c1aaf1a97d1f9'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'El profe no es tan tan mala persona como dicen, no da el curso hace muchos años y se le puede hacer tedioso entenderle, pero si usted pregunta el profe accede a ayudar. En mi caso tuve que ser autodidacta ya que en momentos me perdía mucho. Los exámenes suelen ser algo complejos y largos.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '376a8e32365b8a3afc84c4e229ac0b1f39bb26873e1e4ed47d5cf75d3ddf5ff9'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'NO MATRICULEN CON ÉL. Si no sabe nada de Python, no matricule con él. No sabe explicar, se desvía del tema DEMASIADO. Los exámenes no tienen nada que ver con la materia que da en clases, le baja puntos por cualquier vara.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'b79b969cad704660743459f5638084d87cff354b311fe04aed744fe25989bec5'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'NO SABE NADA DE PYTHON Y NO SABE EXPLICAR NADA'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'de77dd4590dfeceaa7ad1eb6c2d4535a8ceeda2c0573f02f0d08febab293920c'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'El profe no da el curso de elementos hace muchos años, por lo que a veces se vuelve tedioso entenderle. Vaya a todas las clases, participe, pregunte sus dudas siempre y el profe le va a ayudar. Al final del curso él va a tomar en cuenta todo eso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'aaf46a83dc5418ceead0965f41bd48c8eff1fd363176f13c1d8501d632bf182b'::TEXT, ARRAY[1249]::BIGINT[]),
    (303::BIGINT, 'Pasar con Franco no es tan complicado, al final la clave está en ganarse su confianza, entre más consultas y preguntas sobre los proyectos le haga, más suave se lo va a calificar. Eso si, las clases son bastante aburridas, se desvía demasiado de los temas y los exámenes son difíciles.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa']::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, '2b705745eedf0ddf09d9ae8dbe6a14d52d56b1bee5ab957f1ed08cb350dfa310'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Su método de enseñanza no es el mejor. Lo pedido en los proyectos fue poco claro y hasta él lo admitió. Le da mucha importancia a la participación. Los exámenes y quices son difíciles. Se desvía del tema para hablar de cosas raras.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f0e145d90d9ca8336e371c523f3e8c0d4799d8d93d25d358fe28d979f9a32afa'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Es complicado. Usted lo va a escuchar hablar de su vida, de su religión y de regiones indígenas. Demuestre que usted es honesto y él se lo reconcerá, además siempre está anuente a apoyar. Hace quices sorpresa. Es perfectamente posible, más si a usted le gusta programar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ac4c11d988b9040ecdb9ec24651f0a007d9e04ecf4362404c0b923218f511e3f'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Nunca había odiado tanto a un ser humano, hice revisiones a las 3am con un señor que parece que no quiere ni vivir, que te dice hasta de lo que te vas a morir y que su único objetivo en el chat del grupo es pelear, NO lo haga compa, si eso es un profe, yo soy director de carrera'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-04-23T00:00:00+00:00'::TIMESTAMPTZ, '4b1b694eeb48a561e0eaf2edc73e976c85a7ac549bdb5f4f24eace008946def4'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Si solo tiene de opción matricular con este profesor, deje el curso para el siguiente semestre. Es mejor que llevarlo con él. Humilla a los estudiantes. La revisión de proyectos es literalmente lo que él quiera, califica funcionalidades que nunca pidió. Exámenes difíciles y quizes sorpresa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-12-21T00:00:00+00:00'::TIMESTAMPTZ, '2de704b758376c51319b04397b23da1e40abdd41d1ba6c50f6d0da67869d7bcf'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Bases de Datos I es un curso muy importante para la carrera y en Cartago no suelen haber buenos profes para él, así que aquí le dejo una reseña de cómo pasar el curso con Franco. https://docs.google.com/document/d/1I7Vp-CN-_wj15uvq2ibxXmaVVCvtGqFlzgCLwePZjv8/edit?usp=sharing'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'a077036945bbb69cc39a93dc2815bf727a4b5aeed3be250553d9a92f3074c280'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Se nota que esta dando clases solo por la deuda masiva que tiene. Es el peor profe que he tenido y en cuanto a actitud es horrible. Y eso que para mi Kirstein era buena gente, ahora que yo diga que este es horrible imaginese'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '1bbdace80bc81ef79610956c6fa3e924693b7c39dc30871a5a0553360c6e9a92'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Las clases fueron verlo escribir en un documento todo lo que decía, hacer ejemplos que no se entendían y escuchar sus historias sobre empresas que han fracasado y como él sabe de eso pero no lo va a explicar, los exámenes son un asco y califica según lo que le de la gana, evítelo si puede'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '3ebbaea44ebe76b1f64ef4468a35b607f86677098eba3ed5b4bb89c8e53a1565'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Evitar matricular con este profesor. La mecánica de sus clases se resume en escucharlo hablar mientras escribe en un documento en Word y aveces da ejemplos de código en SQL, para los modelos no usa herramientas de diagramación. Sus quices se resumen en items de TRUE/FALSE y son bastante confusos.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'adcdf402a32d646b5e5c9428360618f789e4b5994e0a10994dc2fb40c1b96c17'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Es un asco, califica al azar, le encanta humillar a los estudiantes, no enseña nada, uno todo tiene que aprenderlo a punta de videos y se queja cuando uno no hace las cosas en el tiempo en el que él lo hace. Horrible persona, 0 vocación, y todos los trabajos son rudos para valer un 5 o 13%'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, '764274da74fb38b70d457cd4949f37764795949c199e40aa9838b1986f3b947e'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Califica injustamente en todo, si las cosas no se hacen como el quiere posiblemente le va a bajar la mitad de los pts. Las clases son aburridas y hace quices sorpresa. Los exámenes son de dificultad media y los proyectos son largos. Hay que aprender HTML y SQL solo porque nunca explica bien. Pésimo'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd2766043dec6269c0bd0f7b415cd3c6228cfd85a8f3373f0ca040817e280a408'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'En todo el tiempo que llevo en el tec, este es el peor profesor que he tenido. Se nota que no sabe lo que está hablando y pasa más de una clase hablando solo de cómo sus empresas quebraron y tiene una deuda gigante. En las revisiones pareciera que solo quiere desquitarse con uno. No matricular.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-29T00:00:00+00:00'::TIMESTAMPTZ, 'cdbc688a754ddb492abf1b07e1728b976b0ed345a02157cf465e2da9400715da'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'El peor profesor, sin duda. Se nota que no sabe nada de la materia y lo único que hace es hablar de su vida personal. Es un irrespetuoso y su único medio de comunicación son los gritos. Las evaluaciones no son demasiado difíciles, pero siempre cambia las especificaciones a medio camino.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '51e06af8b7659e507b2a867346a97dd515b74077cd07a2663e70a6bf3617f708'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Es increíble el nivel de desorganización, los requerimientos de los proyectos cambian 2 veces por semana, dice que no se puede hacer de X forma 3 días antes de las entregas, a eso súmele aprender SQL, HTML, JS y Webpages, por su cuenta, ni se esfuerza en enseñarlo y espera que usted lo sepa todo'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-05-22T00:00:00+00:00'::TIMESTAMPTZ, '0f57bf4c1cada59ad7801283a1797f780d126315040b15ee07e077c89fea7002'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Se nota que el profe sabe bastante y actualmente está en varios proyectos de bases pero es una completa b*sura para calificar. Si usted no lo hace a la manera de él tiene cero y de paso lo trata re-mal (aunque la solución de uno sea mejor que la de él) Deja todo para lo último. Cero vocación'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'd8e5bab9c7a6aba46b73b59cbae909411041cde0fd940942d7539fb31cff7a3f'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Los temas que explica el profe son muy buenos y les veo de mucha utilidad además explica temas que otros profes tal ves no! Lo malo es que pasa hablando durante toda la lección en todas las clases no hizo ninguna práctica no hay participación de los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '63e14c0017e3fb9e0228f3a14e676b06d39022d2943e3fb16ffadf7cc15fb951'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Se aprecia que tiene pasion por el tema, pero sus cualidades para enseñar no son las mejores. Las clases pueden llegar a ser muy lentas y aburridas. Dejó 4 Proyectos, toman bastante tiempo. Y se realizaron 2 Examenes de dificultad media.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '51533033d755818f74aff198d13e0737cc5e409b4cc1ebc9ed6bf8a91b2f91fb'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Terrible profe, alguien así no está capacitado para enseñar, es una pena ver que la U tenga a alguien así para los futuros ingenieros, basura se le queda corto. Desordenado, cambia las progras por capricho, y deja todo para última hora además de hacerse un 8 cuando explica.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '89a7f7e6398fd9c38f017d29a27aea380d78e00bee5ed2d3fb25a1ee752302f2'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Con este profesor hay que ser demasiado autodidacta, sin embargo, el curso con él se pasa con un 60.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '70fb450329c1285de9a083c1b68d65695b0b4053cf4046114690a6fb5de988dc'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Para el existe una sola solución, la de él. Vas a aprender como conquistar su corazón de tanto que habla de si mismo. Por este tipo de personas es que la gente le pone salsa de tomate a la ensalada. Tiene la cabeza mas densa que un repollo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '314e21480b83650cd5d6b97f95cbc312f0562d7dd002848291ad3633bcd44d7d'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Sinceramente no es tan malo como dicen, definitivamente ha cambiado su manera de dar clases con el tiempo solo que si usted quiere pasar el curso tiene que aprender SQL por cuenta propia y hacer demasiada investigación. Da porcentaje extra en las progras por cualquier cosa y el curso se pasa con 60'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra']::TEXT[], '2019-10-31T00:00:00+00:00'::TIMESTAMPTZ, '9b6a9e86e36300ce9677ac8ef46f11596b97832cd26dd4a11849baa2dc9e16f2'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'No es tan malo como la gente lo plantea, hay que aprender SQL por su cuenta pero si se le pide ayuda en código o explicaciones el profesor es de muy buena ayuda y muy claro. Las progras tienen un nivel de dificultad alto pero realizables, además de que con los proyectos se aprende bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2019-09-02T00:00:00+00:00'::TIMESTAMPTZ, '0e7ac138e1c7552d79a50ce124704123d367cbe902049f54713a9651ae8920bd'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Ha sido el peor profesor que he tenido en mi tiempo en el TEC, en verdad no le importa los estudiantes, le grita a los estudiantes que le hacen reclamos para el examen (En medio laboratorio H) si no hacen las progras como el quiere, baja demasiados puntos si no es igual a la solución de el.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'c761f3f7a05fbc415b0b93fba9ab788c41d9517363d6d2efff1679d33a39ea4a'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'El profe es muy desordenado, hay que ponerle mucha atencion de como quiere que haga las progras, si hace algo diferente a como el dijo baja muchos puntos. En las clases se desvia mucho, sabe del tema pero no es buen profesor.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2019-02-04T00:00:00+00:00'::TIMESTAMPTZ, '8aa727aca4aada3fc1bf31dd4654fe07c40eaa30dbce1edd5b69e1fdef3d2f12'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Lo más importante con este profe es recordar que se pasa con un 60, hay quices casi todas las semanas (25%) pero son fáciles si se va al día con la materia, exámenes de dificultad moderada (30%) y los proyectos (45%) son bastante sencillos pero es importante hacerle consultas al profesor'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Exámenes retadores']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '8885e6b0e98756448ba30fa2c1b09a50a0f4ade88105e3c7e17caadcb242e0ae'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'El profe se pone en muchas varas, califica como le da la gana y trata pesimo a los estudiantes, les grita y no acepta reclamos, si haces algo diferente a lo que el quiere te va a calificar pesimo, es su solucion y ya, en un tema que hay mil soluciones para modelar. Pésimo profesor para mi opinion.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'a48b7b5b996c1719c9580f51685b0b43a8dca8229cc2cf11e37d9f8751966d73'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'El mae no es tan malo. Si van a clases y le preguntan pasan bien. Usualmente se quedan solo los que no van a clases porque hace entre 10 y 11 quices. Exámenes normales, solo hacer los casos que deja porque mete 1 en el examen. Aprender SQL por cuenta propia pero si le piden él explica en clases.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '57a2d18c55d9e8df97508124cfe2ff43242156c479160efec95ab49c9a79d2ab'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Aveces se desvía del tema pero sabe mucho. Si se lo piden explica un poco de SQL pero toca aprender bastante por cuenta propia. Quices y tareas que se ganan fáciles y progras normales si se les dedica el tiempo de un curso de 4 créditos.Ayuda por WA y exámenes normales, ir a clases y estudiar enough'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '184dbab8abb7381cb06cbc20d55e8c674ca7140409f0c4f57669b9968368da4e'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Es un profesor algo peculiar pero muy buena gente , las clases se disfrutan escuchando las historias que cuenta , en términos teóricos es muy bueno sabe del tema, sin embargo a la hora de programar y aprender el lenguaje te toca solo , es mucho mas facil si ya tienes una base de SQL.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e3f99d7adcc6f8efb1c28855eb094c1974cb187e0b7ef393ca831cdc65fea47a'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'A veces no se da a entender muy bien y es un poco desordenado, los quices valen 25% y hace unos 10 si se estudia al día se sacan fáciles, en realidad es un buen profe para llevar el curso aunque si uno no tiene ninguna base puede ser difícil.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c475992e10ad25321fd8f2de2439e6a1b6fde2b18bdf65fd9373ccf71eb40720'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Si se lleva el curso por segunda vez franco es el mejor, solo hay que repasar un día antes lo que se hizo en clases y va a tener 25% de quices asegurados, el mae se desvía mucho pero tiene mucho conocimiento de la materia y enseña cosas que son super útiles que otros profes no dan'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'ee53cd5685d82f3b5f66ff9fe3f244a12d6e94f3d4b361cfacf6d1722bd5bb75'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Va a aprender más de la vida del mae que de la materia'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-28T00:00:00+00:00'::TIMESTAMPTZ, '54805bd3c2c40e545368dd098da501e16523b34b437d4e225d411dc5b53ac67d'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'El profe no es tan malo, si se aprende, nada mas que usted aprende mucho por su cuenta, lo unico que reprocho es que sea muy subjetivo en cuanto a las evaluaciones'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '659ded80208559b9786a7712de2da093a96c7f040678d963966a6ea59582915d'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Las especificaciones de tareas muy confusas. No explica para nada bien y no se aprende NADA. Califica muy muy duro.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7e9a09be5f32e8dd711c40cede2bde194a0bbc5bbe8882e77b67d79fd9ec5784'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Es muy pura vida y le gusta compartir sus experiencias de vida e historias en clase. Las clases son entretenidas y sabe muchísimo pero a veces le cuesta explicar. Los exámenes son sencillos, los quices pasables y las tareas programadas solo revisa el código SQL por lo que hay que pulirse en eso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'f3405a144e8873afe9535afff0c1a780740db961704b91a8db7a18ce6e8072a1'::TEXT, ARRAY[1037]::BIGINT[]),
    (303::BIGINT, 'Sabe de mucho, pero no es nada bueno explicando, mejor llevar con otro profesor en especial Bases de Datos un curso actualmente importante a futuro, no es difícil, algo se aprende pero con el casi nada.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'aa6464b72865a5704d1521f8ef57a214b00636070d5245608632650994fa2774'::TEXT, ARRAY[1037]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
